<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import PotreeFrame from '@/components/PotreeFrame.vue'
import { createAnnotation, createMeasurement, getAnnotations, getMeasurements, getViewerConfig } from '@/api/viewer'
import { getCase } from '@/api/cases'
import type { Annotation, Measurement, Point3D } from '@/types/viewer'
const route=useRoute(),router=useRouter(),frame=ref<InstanceType<typeof PotreeFrame>>(),loading=ref(true),error=ref(''),manifestUrl=ref(''),versionId=ref(''),annotations=ref<Annotation[]>([]),measurements=ref<Measurement[]>([]),point=ref<Point3D>({x:0,y:0,z:0}),title=ref(''),forcedMasks=ref<Array<{id:string;type:'HIDE';title:string;range:{min:[number,number,number];max:[number,number,number]};enforced:true}>>([]),mock=import.meta.env.VITE_USE_MOCK!=='false'
const forcedCount=computed(()=>forcedMasks.value.length)
async function reload(){[annotations.value,measurements.value]=await Promise.all([getAnnotations(versionId.value),getMeasurements(versionId.value)])}async function init(){try{const record=await getCase(String(route.params.caseId)),status=record.latestVersion?.status;if(status==='ARCHIVED')throw new Error('该教学版本已归档，不能进入三维工作台。');if(status!=='READY'&&status!=='PUBLISHED')throw new Error('该案例版本尚未就绪或未发布。');versionId.value=record.latestVersion!.id;const config=await getViewerConfig(versionId.value);manifestUrl.value=config.manifestUrl;forcedMasks.value=config.forcedDesensitizationRules.filter(rule=>rule.mode==='HIDE').map(rule=>({id:rule.id,type:'HIDE',title:rule.title,range:{min:rule.geometry.min,max:rule.geometry.max},enforced:true}));await reload()}catch(e){error.value=e instanceof Error?e.message:'工作台初始化失败'}finally{loading.value=false}}async function savePoint(){if(!title.value.trim())return ElMessage.warning('请输入标记标题');await createAnnotation(versionId.value,{type:'POINT_MARK',geometry:{position:point.value},title:title.value,description:'',viewerState:{camera:{}}});title.value='';await reload()}async function saveMeasure(v:{startPoint:Point3D;endPoint:Point3D}){await createMeasurement(versionId.value,v);await reload()}onMounted(init)
</script>
<template><main class="workspace"><header><div><p>管理员 / 三维工作台</p><h1>点云浏览与标记</h1></div><el-button @click="router.back()">返回详情</el-button></header><el-alert v-if="error" title="无法加载三维工作台" :description="error" type="error" :closable="false" show-icon/><el-skeleton v-else-if="loading" :rows="12" animated/><section v-else class="layout"><div class="viewer"><PotreeFrame ref="frame" :manifest-url="manifestUrl" :mock="mock" :masks="forcedMasks" :hide-preview="true" @error="error=$event" @pick="point=$event" @measurement="saveMeasure"/></div><aside><el-alert v-if="forcedCount" title="教学强制遮挡已生效" :description="`已强制应用 ${forcedCount} 个 HIDE 区域；仅遮挡展示，不代表物理删除。`" type="warning" :closable="false"/><el-button-group><el-button @click="frame?.startPointPick()">新增点标记</el-button><el-button @click="frame?.startMeasurement()">测距</el-button><el-button @click="frame?.resetView()">复位视角</el-button></el-button-group><el-divider>点位标记</el-divider><el-input v-model="title" placeholder="标记标题"/><el-button type="primary" @click="savePoint">保存点标记</el-button><el-divider>标记列表</el-divider><el-empty v-if="!annotations.length" description="暂无标记"/><p v-for="item in annotations" :key="item.id">{{item.title}}</p><el-divider>测距列表</el-divider><p v-for="item in measurements" :key="item.id">{{Math.hypot(item.startPoint.x-item.endPoint.x,item.startPoint.y-item.endPoint.y,item.startPoint.z-item.endPoint.z).toFixed(2)}} m</p></aside></section></main></template>
<style scoped>.workspace{height:100vh;background:#f4f7fb}header{height:76px;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;background:#fff}header p{margin:0;color:#64748b;font-size:12px}h1{margin:5px 0;font-size:20px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;height:calc(100vh - 76px)}aside{padding:16px;overflow:auto;background:#fff;border-left:1px solid #dde4ee}@media(max-width:1100px){.layout{grid-template-columns:1fr}.viewer{height:55vh}}</style>
